import assert from 'node:assert/strict';
import { randomUUID, createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
const [worktree, output] = process.argv.slice(2);
const req = createRequire(join(worktree, 'package.json'));
req('./scripts/ci-environment.ts').assertCiDatabaseTarget();
const { PrismaClient, Prisma } = req('@prisma/client');
const { ALLERGEN_MASTER } = req('./lib/constants/allergen-master.ts');
const db = new PrismaClient({ log: [] });
const results=[]; const shops=[];
try {
 const version=await db.$queryRaw`SELECT current_setting('server_version') AS version`;
 const master=await db.allergen.findMany({select:{slug:true},orderBy:{slug:'asc'}});
 assert.deepEqual(master.map(a=>a.slug),ALLERGEN_MASTER.map(a=>a.slug).sort());
 results.push({check:'master-set',status:'PASS',codeCount:ALLERGEN_MASTER.length,dbCount:master.length});
 const enums=await db.$queryRaw`SELECT unnest(enum_range(NULL::"AllergenStatus"))::text AS value`;
 assert.deepEqual(enums.map(r=>r.value).sort(),['CONTAINS','FREE','MAY_CONTAIN','UNKNOWN'].sort());
 results.push({check:'allergen-enum',status:'PASS',values:enums.map(r=>r.value)});
 const migrations=await db.$queryRaw`SELECT migration_name, finished_at IS NOT NULL AND rolled_back_at IS NULL AS applied FROM "_prisma_migrations" ORDER BY migration_name`;
 assert.equal(migrations.length,16); assert.ok(migrations.every(r=>r.applied));
 const triggers=await db.$queryRaw`SELECT tgname AS name, tgdeferrable AS deferrable, tginitdeferred AS initially_deferred FROM pg_trigger WHERE NOT tgisinternal AND tgname IN ('MenuItem_reconcile_publication','MenuItemAllergen_reconcile_publication','Allergen_reconcile_menu_publication') ORDER BY tgname`;
 assert.equal(triggers.length,3); assert.ok(triggers.every(r=>r.deferrable&&r.initially_deferred));
 results.push({check:'applied-publication-triggers',status:'PASS',triggers});
 const indexes=await db.$queryRaw`SELECT indexname AS name, indexdef AS definition FROM pg_indexes WHERE schemaname='public' AND indexname IN ('AdminInvite_pending_email_key','AdminInvite_pending_shopId_key') ORDER BY indexname`;
 assert.equal(indexes.length,2); assert.ok(indexes.every(r=>r.definition.includes('UNIQUE')&&r.definition.includes('WHERE')&&r.definition.includes('pending')));
 results.push({check:'applied-pending-unique-indexes',status:'PASS',indexes});
 const shop=await db.shop.create({data:{name:`fictional release check ${randomUUID()}`,isActive:true}}); shops.push(shop.id);
 const all=await db.allergen.findMany({select:{id:true}});
 const incomplete=await db.menuItem.create({data:{shopId:shop.id,name:'fictional missing',isPublished:true}});
 assert.equal((await db.menuItem.findUniqueOrThrow({where:{id:incomplete.id}})).isPublished,false);
 results.push({check:'missing-links-unpublish',status:'PASS'});
 const full=await db.menuItem.create({data:{shopId:shop.id,name:'fictional MAY_CONTAIN',isPublished:true,allergenLinks:{create:all.map((a,i)=>({allergenId:a.id,status:i===0?'MAY_CONTAIN':'FREE'}))}}});
 assert.equal((await db.menuItem.findUniqueOrThrow({where:{id:full.id}})).isPublished,true);
 results.push({check:'complete-MAY_CONTAIN-published',status:'PASS'});
 await db.menuItemAllergen.update({where:{menuItemId_allergenId:{menuItemId:full.id,allergenId:all[0].id}},data:{status:'UNKNOWN'}});
 assert.equal((await db.menuItem.findUniqueOrThrow({where:{id:full.id}})).isPublished,false);
 results.push({check:'UNKNOWN-unpublish',status:'PASS'});
 const before=await db.menuItem.count({where:{shopId:shop.id}});
 await assert.rejects(db.$transaction(async tx=>{await tx.menuItem.create({data:{shopId:shop.id,name:'fictional rollback'}});throw new Error('fixture rollback');}),/fixture rollback/);
 assert.equal(await db.menuItem.count({where:{shopId:shop.id}}),before);
 results.push({check:'transaction-rollback',status:'PASS'});
 const invite={email:`fictional-${randomUUID()}@example.invalid`,shopId:shop.id,invitedByClerkUserId:'fictional-release-check'};
 await db.adminInvite.create({data:invite});
 const isDuplicate=e=>e instanceof Prisma.PrismaClientKnownRequestError&&e.code==='P2002';
 await assert.rejects(db.adminInvite.create({data:{...invite,email:`fictional-${randomUUID()}@example.invalid`}}),isDuplicate);
 const second=await db.shop.create({data:{name:'fictional pending email boundary'}}); shops.push(second.id);
 await assert.rejects(db.adminInvite.create({data:{...invite,shopId:second.id}}),isDuplicate);
 await db.adminInvite.create({data:{...invite,status:'revoked'}});
 results.push({check:'pending-shop-email-uniqueness-and-revoked-coexistence',status:'PASS'});
 const source=readFileSync(fileURLToPath(import.meta.url),'utf8');
 writeFileSync(output,JSON.stringify({collectedAt:new Date().toISOString(),baseSha:'1830a98fd4f8b60e9621417a5b843a4e42e0d81a',scope:'throwaway local CI-guarded PostgreSQL; fictional fixture only',productionApplied:'UNKNOWN',serverVersion:version[0].version,migrations,results,collectorSourceSha256:createHash('sha256').update(source).digest('hex'),collectorSource:source,limitations:['Not production database or deployed services','No actual Clerk/Blob integration','Original source assertions use the CI guard for localhost rather than the Compose hostname','No schema changes or new migrations']},null,2));
 console.log(JSON.stringify({status:'PASS',groups:results.length,version:version[0].version,migrations:migrations.length,results:results.map(r=>r.check)}));
} finally {
 await db.auditLog.deleteMany({where:{actorShopId:{in:shops}}});
 await db.shop.deleteMany({where:{id:{in:shops}}});
 await db.$disconnect();
}
